syntax:
def decorador(func):
    def wrapper(*args, **kwargs):
        # antes
        resultado = func(*args, **kwargs)
        # depois
        return resultado
    return wrapper

@decorador
def minha_funcao(): ...

example:
def log_chamada(func):
    def wrapper(*args, **kwargs):
        print(f"Chamando {func.__name__}")
        return func(*args, **kwargs)
    return wrapper

@log_chamada
def somar(a, b):
    return a + b

syntax:
def gerador():
    yield valor1
    yield valor2

example:
def contador(limite):
    n = 0
    while n < limite:
        yield n
        n += 1

for i in contador(3):
    print(i)

