syntax:
class Nome:
    @property
    def atributo(self):
        return self._atributo
    @atributo.setter
    def atributo(self, valor):
        self._atributo = valor

example:
class Circulo:
    def __init__(self, raio):
        self._raio = raio
    @property
    def area(self):
        return 3.14159 * self._raio ** 2

c = Circulo(2)
print(c.area)

class Vetor:
    def __init__(self, x, y):
        self.x, self.y = x, y
    def __repr__(self):
        return f"Vetor({self.x}, {self.y})"
    def __add__(self, outro):
        return Vetor(self.x + outro.x, self.y + outro.y)

print(Vetor(1, 2) + Vetor(3, 4))

